def _record_tool_failure(event, exc):
    path = _failure_map_path()
    try:
        data = _load_failure_map(path)
        tool = event["tool"]
        _bump_count(data, "failures", tool)
        data["events"].append({
            "kind": "failure",
            "tool": tool,
            "error_type": type(exc).__name__,
            "error": str(exc),
            "ts": time.time(),
        })
        _write_failure_map(path, data)
    except OSError:
        pass

