def _chapter_title(cell):
    if getattr(cell, "cell_type", None) != "markdown": return None
    for line in _cell_source(cell).splitlines():
        match = re.match(r"^##\s+(.+?)\s*$", line.strip())
        if match: return match.group(1).strip()
    return None

